customize.css:
/* An admin-dashboard look: a dark top bar, a white page with a large light title, bordered cards with a grey header bar, blue links and buttons,
   small uppercase section labels. Written for this blog's own markup from the dashboard's layout and palette; no stylesheet or font was copied. */
:root{color-scheme:light;--fg:#212529;--bg:#fff;--link:#0d6efd;--muted:#6c757d;--rule:#dee2e6;--code:#f8f9fa;--dark:#212529;--blue:#0d6efd;--bar:#f8f9fa;--font:system-ui,-apple-system,"Segoe UI",Roboto,"Helvetica Neue",Arial,sans-serif;--heading-font:system-ui,-apple-system,"Segoe UI",Roboto,"Helvetica Neue",Arial,sans-serif}
body{background:#fff;color:var(--fg);font-family:var(--font);font-size:1rem;line-height:1.5;overflow-x:hidden}
.wrap{max-width:1140px;padding:0 1.5rem 3rem}
a{color:var(--blue);text-decoration:underline}
a:hover{color:#0a58ca}
header.site{display:flex;align-items:center;justify-content:space-between;flex-wrap:wrap;gap:.5rem 1.5rem;margin:0 0 2rem;padding:0;min-height:56px;border:0;background:var(--dark);box-shadow:0 0 0 100vmax var(--dark);clip-path:inset(0 -100vmax)}
header.site a.brand{color:#fff;font-size:1.25rem;font-weight:500;text-decoration:none}
header.site a.brand::before{content:none}
header.site nav{display:flex;flex-wrap:wrap;align-items:center;gap:.1rem .25rem}
header.site nav a{margin:0;padding:.5rem .75rem;color:rgba(255,255,255,.6);font-size:.95rem;text-decoration:none;border-radius:6px}
header.site nav a::before{content:none}
header.site nav a:hover{color:#fff;background:rgba(255,255,255,.08)}
h1,h2,h3{color:var(--fg);font-weight:500;line-height:1.2}
h1::before,h2::before,h3::before,ul.posts h2::before{content:none}
h1{font-size:clamp(2rem,5vw,2.5rem);margin:0 0 .5rem}
h2{font-size:1.5rem}
h3{font-size:1.2rem}
body>.wrap>h1+.meta{margin:0 0 1.5rem;padding:0 0 1rem;border-bottom:1px solid var(--rule);color:var(--muted);font-size:1rem;letter-spacing:0;text-transform:none;font-weight:400}
.meta{color:var(--muted);font-size:.8rem}
.meta .tag{display:inline-block;margin:0 0 0 .4rem;padding:.25em .6em;background:var(--blue);border-radius:.375rem;color:#fff;font-size:.72rem;font-weight:700;line-height:1;text-decoration:none}
.meta .tag:hover{background:#0a58ca;color:#fff}
ul.posts{list-style:none;padding:0;margin:0 0 1.5rem;display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:1.5rem}
ul.posts li{display:flex;flex-direction:column;margin:0;padding:0;background:#fff;border:1px solid var(--rule);border-radius:.375rem;overflow:hidden}
ul.posts h2{order:1;margin:0;padding:.75rem 1rem;background:var(--bar);border-bottom:1px solid var(--rule);font-size:1rem;font-weight:500;line-height:1.4}
ul.posts h2 a{color:var(--fg);text-decoration:none}
ul.posts h2 a:hover{color:var(--blue)}
ul.posts .thumb{order:2;display:block;aspect-ratio:16/9;overflow:hidden;background:var(--bar)}
ul.posts .thumb img{width:100%;height:100%;object-fit:cover;border:0;border-radius:0}
ul.posts p{order:3;flex:1;margin:0;padding:1rem;color:#495057;font-size:.95rem}
ul.posts .meta{order:4;margin:0;padding:.6rem 1rem;background:var(--bar);border-top:1px solid var(--rule);font-size:.8rem}
article{max-width:50rem;margin:0}
article h1{margin:0 0 .4rem;font-size:clamp(2rem,5vw,2.5rem)}
article .meta{margin-bottom:1.5rem;padding-bottom:1rem;border-bottom:1px solid var(--rule)}
article a{overflow-wrap:anywhere}
img{border:0;border-radius:.375rem}
.cover img{border-radius:.375rem}
blockquote{margin:1.25rem 0;padding:.5rem 1rem;border-left:.25rem solid var(--rule);color:var(--muted);font-size:1.15rem}
pre{background:var(--code);border:1px solid var(--rule);border-radius:.375rem}
code{background:var(--code);border-radius:.25rem;color:#d63384}
pre code{background:none;color:inherit}
table{border-collapse:collapse;width:100%}
th{background:#fff;border-bottom:2px solid var(--fg);font-weight:700}
th,td{border:1px solid var(--rule);padding:.5rem .6rem}
hr{border:0;border-top:1px solid var(--rule)}
.post-nav,.navigation.pagination .nav-links{display:flex;justify-content:space-between;gap:1rem;margin-top:1.5rem}
.post-nav a,.navigation.pagination a{max-width:48%;padding:.375rem .85rem;background:var(--blue);border:1px solid var(--blue);border-radius:.375rem;color:#fff;font-size:1rem;text-decoration:none}
.post-nav a:hover,.navigation.pagination a:hover{background:#0b5ed7;border-color:#0a58ca;color:#fff}
form[role=search] input,form.subscribe input{padding:.375rem .75rem;border:1px solid #ced4da;border-radius:.375rem;background:#fff;color:var(--fg)}
form[role=search] input:focus,form.subscribe input:focus{border-color:#86b7fe;box-shadow:0 0 0 .25rem rgba(13,110,253,.25);outline:0}
form[role=search] button,form.subscribe button{padding:.375rem .85rem;border:1px solid var(--blue);border-radius:.375rem;background:var(--blue);color:#fff;cursor:pointer}
footer.site{margin:2rem 0 0;padding:1rem 0;border:0;background:var(--bar);box-shadow:0 0 0 100vmax var(--bar);clip-path:inset(0 -100vmax);color:var(--muted);font-size:.875rem}
footer.site a{color:var(--muted)}
::selection{background:#b6d4fe;color:var(--fg)}
@media (max-width:760px){ul.posts{grid-template-columns:1fr}.wrap{padding:0 1rem 2rem}}
